<?php $pageTitle='Evaluaciones';$pageSubtitle='Crea evaluaciones y consulta el estado de tus pruebas.';require __DIR__.'/../partials/header.php'; ?><div class="grid"><?php foreach($evaluaciones as $e): ?><div class="card"><h3><?=htmlspecialchars($e['titulo_evaluacion'])?><?php if((int)$e['id_estado_e']===3): ?><span class="badge cerrada">Cerrada</span><?php endif; ?></h3><p><?=htmlspecialchars($e['descripcion_evaluacion'])?></p><div class="meta"><span><?=htmlspecialchars($e['titulo_evaluacion']??'')?></span><span><?=$e['preguntas']?> preguntas</span><span>Aprueba: <?=$e['puntaje_aprobacion']?></span></div><div class="actions"><?php if((int)$e['id_estado_e']===1): ?><a class="btn btn-primary" href="index.php?route=crear-pregunta&evaluacion=<?=$e['id_evaluacion']?>">+ Pregunta</a><form method="post" action="index.php?route=cerrar-evaluacion" style="display:inline"><input type="hidden" name="evaluacion" value="<?=$e['id_evaluacion']?>"><input type="hidden" name="curso" value="<?=$e['id_curso_e']?>"><button type="submit" class="btn btn-secondary" onclick="return confirm('¿Cerrar esta evaluación? No se podrán agregar más preguntas.')">Cerrar</button></form><?php else: ?><span class="badge cerrada">Cerrada</span><?php endif; ?></div></div><?php endforeach; ?><?php if(!$evaluaciones): ?><div class="empty">No tienes evaluaciones creadas todavía.</div><?php endif; ?></div><?php require __DIR__.'/../partials/footer.php'; ?>
